-- Initial schema; do not run against production without explicit approval.
create extension if not exists pgcrypto;
create table public.marketplaces (id uuid primary key default gen_random_uuid(), slug text not null unique check (slug ~ '^[a-z0-9_]+$'), name text not null, created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, parent_category_id uuid references public.categories(id), created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), category_id uuid references public.categories(id), slug text not null unique, name text not null, brand_name text, description text, publication_status text not null default 'draft' check(publication_status in ('draft','published','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_variants (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, sku text, variant_attributes jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index product_variants_product_id_idx on public.product_variants(product_id);
create table public.merchants (id uuid primary key default gen_random_uuid(), marketplace_id uuid not null references public.marketplaces(id), external_merchant_id text, display_name text not null, is_verified boolean not null default false, created_at timestamptz not null default now(), unique(marketplace_id,external_merchant_id));
create index merchants_marketplace_id_idx on public.merchants(marketplace_id);
create table public.offers (id uuid primary key default gen_random_uuid(), product_variant_id uuid not null references public.product_variants(id), merchant_id uuid not null references public.merchants(id), external_listing_id text, source_url text, price_amount_minor bigint check(price_amount_minor >= 0), currency_code char(3) not null default 'PHP', last_verified_at timestamptz, publication_status text not null default 'draft' check(publication_status in ('draft','published','suspended')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(merchant_id,external_listing_id));
create index offers_product_variant_id_idx on public.offers(product_variant_id);
create index offers_merchant_id_idx on public.offers(merchant_id);
create table public.price_observations (id uuid primary key default gen_random_uuid(), offer_id uuid not null references public.offers(id), price_amount_minor bigint not null check(price_amount_minor >= 0), currency_code char(3) not null, observed_at timestamptz not null, source_name text not null, source_reference text, includes_shipping boolean not null default false, created_at timestamptz not null default now());
create index price_observations_offer_observed_idx on public.price_observations(offer_id,observed_at desc);
create table public.affiliate_programs (id uuid primary key default gen_random_uuid(), marketplace_id uuid references public.marketplaces(id), name text not null, approval_status text not null default 'pending' check(approval_status in ('pending','approved','rejected','suspended')), created_at timestamptz not null default now());
create table public.affiliate_links (id uuid primary key default gen_random_uuid(), offer_id uuid not null references public.offers(id), affiliate_program_id uuid not null references public.affiliate_programs(id), destination_url text not null check(destination_url ~ '^https://'), is_active boolean not null default false, expires_at timestamptz, created_at timestamptz not null default now());
create index affiliate_links_offer_id_idx on public.affiliate_links(offer_id);
create table public.trend_signals (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id), source_name text not null, metric_name text not null, metric_value numeric not null, observed_at timestamptz not null, created_at timestamptz not null default now());
create index trend_signals_product_observed_idx on public.trend_signals(product_id,observed_at desc);
create table public.product_scores (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id), ranking_version text not null, value_score numeric not null check(value_score between 0 and 100), trend_score numeric not null check(trend_score between 0 and 100), quality_score numeric not null check(quality_score between 0 and 100), affordability_score numeric not null check(affordability_score between 0 and 100), reliability_score numeric not null check(reliability_score between 0 and 100), total_score numeric not null check(total_score between 0 and 100), calculated_at timestamptz not null default now());
create index product_scores_product_calculated_idx on public.product_scores(product_id,calculated_at desc);
create table public.outbound_clicks (id uuid primary key default gen_random_uuid(), affiliate_link_id uuid not null references public.affiliate_links(id), occurred_at timestamptz not null default now(), attribution_reference text);
create index outbound_clicks_link_occurred_idx on public.outbound_clicks(affiliate_link_id,occurred_at desc);
create table public.conversion_reports (id uuid primary key default gen_random_uuid(), affiliate_program_id uuid not null references public.affiliate_programs(id), external_conversion_id text not null, attribution_reference text, commission_amount_minor bigint not null check(commission_amount_minor>=0), currency_code char(3) not null, conversion_status text not null check(conversion_status in ('pending','approved','reversed','paid')), occurred_at timestamptz not null, unique(affiliate_program_id,external_conversion_id));
create table public.ingestion_runs (id uuid primary key default gen_random_uuid(), source_name text not null, run_status text not null check(run_status in ('started','succeeded','failed')), started_at timestamptz not null default now(), finished_at timestamptz, imported_count integer not null default 0 check(imported_count>=0), error_details jsonb);
create table public.editorial_reviews (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id), review_status text not null check(review_status in ('pending','approved','rejected')), notes text, reviewer_user_id uuid references auth.users(id), reviewed_at timestamptz, created_at timestamptz not null default now());
create index editorial_reviews_product_id_idx on public.editorial_reviews(product_id);
-- Deny public API access by default. App services require explicit grants/policies after security review.
do $$ declare t text; begin foreach t in array array['marketplaces','categories','products','product_variants','merchants','offers','price_observations','affiliate_programs','affiliate_links','trend_signals','product_scores','outbound_clicks','conversion_reports','ingestion_runs','editorial_reviews'] loop execute format('alter table public.%I enable row level security', t); execute format('revoke all on public.%I from anon, authenticated',t); end loop; end $$;
